&lt;!-- ui --&gt;
&lt;!doctype html&gt;&lt;meta charset=&quot;utf-8&quot;&gt;&lt;title&gt;回答のボタンの状態&lt;/title&gt;
&lt;link rel=&quot;stylesheet&quot; href=&quot;https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@400;700&amp;display=swap&quot;&gt;
&lt;style&gt;
:root{--paper:#eef1ef;--card:#f8faf9;--ink:#111d1a;--muted:#5b6b66;--rule:#b9c7c2;--key:#0d5c55;--key-soft:#d5e6e3;
--font:&quot;Zen Kaku Gothic New&quot;,&quot;Hiragino Kaku Gothic ProN&quot;,sans-serif}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--font);padding:20px}
table{border-collapse:collapse;background:var(--card);border:1px solid var(--rule);border-radius:6px}
th,td{padding:10px 14px;border-bottom:1px solid var(--rule);text-align:left;font-size:13px}
th{color:var(--muted);font-weight:700;font-size:12px}
.vb{font:inherit;font-size:14px;padding:7px 16px;border-radius:6px;border:1px solid var(--rule);background:var(--card);color:var(--ink)}
.vb.pressed{background:var(--key);border-color:var(--key);color:var(--card);font-weight:700}
.vb.focus{outline:2px solid var(--key);outline-offset:2px}
.vb.disabled{opacity:.45}
td small{color:var(--muted)}
&lt;/style&gt;
&lt;table&gt;
&lt;tr&gt;&lt;th&gt;状態&lt;/th&gt;&lt;th&gt;承認する&lt;/th&gt;&lt;th&gt;差し戻す&lt;/th&gt;&lt;th&gt;まだ答えない&lt;/th&gt;&lt;th&gt;使うトークン&lt;/th&gt;&lt;/tr&gt;
&lt;tr&gt;&lt;td&gt;通常&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb&quot;&gt;承認する&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb&quot;&gt;差し戻す&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb&quot;&gt;まだ答えない&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;small&gt;card ・ rule ・ ink&lt;/small&gt;&lt;/td&gt;&lt;/tr&gt;
&lt;tr&gt;&lt;td&gt;押した&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb pressed&quot;&gt;承認する&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb pressed&quot;&gt;差し戻す&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb pressed&quot;&gt;まだ答えない&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;small&gt;key（どのボタンも同じ）&lt;/small&gt;&lt;/td&gt;&lt;/tr&gt;
&lt;tr&gt;&lt;td&gt;焦点（キーボード）&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb focus&quot;&gt;承認する&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb focus&quot;&gt;差し戻す&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb focus&quot;&gt;まだ答えない&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;small&gt;key の外枠&lt;/small&gt;&lt;/td&gt;&lt;/tr&gt;
&lt;tr&gt;&lt;td&gt;無効&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb disabled&quot;&gt;承認する&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb disabled&quot;&gt;差し戻す&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;button class=&quot;vb disabled&quot;&gt;まだ答えない&lt;/button&gt;&lt;/td&gt;&lt;td&gt;&lt;small&gt;透明度 .45&lt;/small&gt;&lt;/td&gt;&lt;/tr&gt;
&lt;/table&gt;
